mapper.select:
		select
			NVL(MAX(
				TO_NUMBER(






                        NVL(substr(BUS_VOUCHNUM,-8),'00000000')

			)),'000000')
		from
			BOK_VOUCH_MAIN
		where
			VOUCH_YEAR = #{vouchYear}
			AND VOUCH_MONTH = #{vouchMonth}
			AND BOOKSET_ID = #{booksetId}

mapper.update:
update BOK_VOUCH_MAIN
set BUS_VOUCHNUM = substr(BUS_VOUCHNUM,0,length(BUS_VOUCHNUM)-6) || '00' || substr(BUS_VOUCHNUM,-6)
where VOUCH_YEAR = #{vouchYear} AND VOUCH_MONTH = #{vouchMonth}

mapper.select:
select * from BOK_DETAIL_ID bokdeal
where 1=1

	and bokdeal.bookset_Id=#{booksetId,jdbcType=VARCHAR}


	and bokdeal.busi_Id=#{busiId,jdbcType=VARCHAR}


	and bokdeal.busi_detail_type=#{busiDetailType,jdbcType=VARCHAR}
